arguments.command:
cd /workspace && python3 -I -c "
import json
rows=[]
for line in open('results/run100/metrics.jsonl'):
    d=json.loads(line)
    rows.append(d)
print('steps:', len(rows), [r['step'] for r in rows][:5], '...', [r['step'] for r in rows][-3:])
for r in rows:
    if r['step']%10==0 or r['step']==1:
        d=r['data']
        keys=[k for k in d if 'val' in k or 'reward' in k and 'critic' in k or k in ('training/global_step',)]
        sel={k:d[k] for k in ['critic/score/mean','critic/rewards/mean','actor/entropy','actor/kl_loss','actor/grad_norm','response_length/clip_ratio','response_length/mean','actor/pg_clipfrac'] if k in d}
        val={k:v for k,v in d.items() if k.startswith('val')}
        print(r['step'], sel, val)
"

